CREATE OR REPLACE FUNCTION public.commit_study_answer(p_id uuid,p_user uuid,p_version integer,p_answer jsonb,p_score integer,p_reaction double precision,p_hub jsonb DEFAULT NULL) RETURNS public.study_attempts LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.study_attempts; topic_name text; question_key text; old_questions jsonb; old_question jsonb; new_question jsonb; correct boolean; recovery integer; missed boolean; BEGIN SELECT * INTO result FROM public.study_attempts WHERE id=p_id AND user_id=p_user FOR UPDATE; IF NOT FOUND OR result.completed OR result.version<>p_version THEN RAISE EXCEPTION 'Attempt changed. Reload to continue.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.app_allowlist a JOIN auth.users u ON lower(u.email)=a.email WHERE u.id=p_user) THEN RAISE EXCEPTION 'Forbidden'; END IF; IF NOT result.free_slot AND NOT public.has_pro_access(p_user) THEN RAISE EXCEPTION 'Pro access required'; END IF; UPDATE public.study_attempts SET answers=answers||jsonb_build_array(p_answer),version=version+1,completed=jsonb_array_length(answers)+1=jsonb_array_length(payload),score=p_score,average_reaction=NULLIF(p_reaction,0),updated_at=now() WHERE id=p_id RETURNING * INTO result; IF result.completed AND result.feature='exam' THEN INSERT INTO public.mock_test_history(user_id,score_pct,state) VALUES(p_user,p_score,result.state); END IF; IF p_hub IS NOT NULL THEN topic_name:=p_hub->>'topic'; question_key:=p_hub->'question'->>'key'; correct:=(p_hub->>'correct')::boolean; IF topic_name NOT IN ('signs','intersections','substances','speed') OR question_key IS NULL THEN RAISE EXCEPTION 'Invalid topic answer'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text||result.state||topic_name,0)); SELECT questions INTO old_questions FROM public.test_hub_progress WHERE user_id=p_user AND state=result.state AND topic=topic_name FOR UPDATE; old_questions:=COALESCE(old_questions,'{}'::jsonb); old_question:=old_questions->question_key; recovery:=CASE WHEN correct AND COALESCE((old_question->>'missed')::boolean,false) THEN COALESCE((old_question->>'recovery')::integer,0)+1 ELSE 0 END; missed:=NOT correct OR (COALESCE((old_question->>'missed')::boolean,false) AND recovery<2); new_question:=jsonb_build_object('question',p_hub->'question','correct',correct,'everCorrect',correct OR COALESCE((old_question->>'everCorrect')::boolean,(old_question->>'correct')::boolean,false),'missed',missed,'recovery',CASE WHEN missed THEN recovery ELSE 0 END); INSERT INTO public.test_hub_progress(user_id,state,topic,questions,last_score,updated_at) VALUES(p_user,result.state,topic_name,jsonb_set(old_questions,ARRAY[question_key],new_question,true),CASE WHEN result.completed AND result.feature<>'review' THEN p_score ELSE NULL END,now()) ON CONFLICT(user_id,state,topic) DO UPDATE SET questions=excluded.questions,last_score=COALESCE(excluded.last_score,test_hub_progress.last_score),updated_at=now(); END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.commit_study_answer(uuid,uuid,integer,jsonb,integer,double precision,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.commit_study_answer(uuid,uuid,integer,jsonb,integer,double precision,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.validate_study_payload() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF jsonb_typeof(NEW.payload)<>'array' OR jsonb_array_length(NEW.payload)<1 THEN RAISE EXCEPTION 'A study attempt needs an authored session'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_study_payload BEFORE INSERT ON public.study_attempts FOR EACH ROW EXECUTE FUNCTION public.validate_study_payload();